"""Quality-checked synthetic training examples, generated by MOTH itself (no download, CC0).

Each example is verified before it is emitted, so a wrong example can never reach training:

* ``arithmetic`` — addition, subtraction, multiplication and division with whole-number results;
  the answer is computed exactly and re-checked from the question text.
* ``instructions`` — short, checkable instructions (repeat, upper-case, count letters, sort, pick the
  larger number, reverse a word); the reply is produced by the operation itself and re-checked.
* ``python`` — small Python functions with a docstring; each one is executed against its tests in an
  isolated namespace (no imports, no builtins beyond a safe set) and kept only if every test passes.

Examples are deterministic for a seed, so builds are reproducible. The evaluation benchmarks (GSM8K
word problems, ARC, MBPP) are not generated here; the library build's decontamination still applies.
"""

from __future__ import annotations

import random
import re
from typing import Any, Callable, Iterator

KINDS = ("arithmetic", "instructions", "python")
WORDS = ["moth", "river", "garden", "rocket", "pencil", "planet", "violin", "lantern", "harbor", "meadow",
         "crystal", "falcon", "thunder", "pepper", "window", "summer", "orbit", "maple", "anchor", "copper"]
SAFE_BUILTINS = {"len": len, "range": range, "sum": sum, "min": min, "max": max, "sorted": sorted, "abs": abs,
                 "reversed": reversed, "list": list, "str": str, "int": int, "enumerate": enumerate, "all": all,
                 "any": any, "set": set, "isinstance": isinstance, "bool": bool}


def _msgs(q: str, a: str) -> list[dict[str, str]]:
    return [{"role": "user", "content": q}, {"role": "assistant", "content": a}]


# ---- arithmetic -------------------------------------------------------------------------------------------
def arithmetic(rng: random.Random) -> tuple[str, str] | None:
    op = rng.choice("+-*/")
    if op == "+":
        a, b = rng.randint(0, 999), rng.randint(0, 999)
        r = a + b
    elif op == "-":
        a, b = rng.randint(0, 999), rng.randint(0, 999)
        r = a - b
    elif op == "*":
        a, b = rng.randint(0, 99), rng.randint(0, 99)
        r = a * b
    else:
        b, r = rng.randint(1, 30), rng.randint(0, 50)
        a = b * r
    sym = {"+": "+", "-": "-", "*": "×", "/": "÷"}[op]
    q = rng.choice([f"What is {a} {sym} {b}?", f"Calculate {a} {sym} {b}.", f"{a} {sym} {b} = ?"])
    ans = f"{a} {sym} {b} = {r}. The answer is {r}."
    # re-check from the text itself
    m = re.search(r"(-?\d+) ([+\-×÷]) (-?\d+)", q)
    x, s, y = int(m.group(1)), m.group(2), int(m.group(3))
    check = {"+": x + y, "-": x - y, "×": x * y, "÷": x // y if y and x % y == 0 else None}[s]
    return (q, ans) if check == r else None


# ---- instructions -----------------------------------------------------------------------------------------
def instructions(rng: random.Random) -> tuple[str, str] | None:
    w = rng.choice(WORDS)
    kind = rng.randrange(6)
    if kind == 0:
        n = rng.randint(2, 4)
        return f"Repeat the word \"{w}\" {n} times, separated by spaces.", " ".join([w] * n)
    if kind == 1:
        return f"Write \"{w}\" in capital letters.", w.upper()
    if kind == 2:
        ch = rng.choice(sorted(set(w)))
        return f"How many times does the letter \"{ch}\" appear in \"{w}\"?", \
            f"The letter \"{ch}\" appears {w.count(ch)} time{'s' if w.count(ch) != 1 else ''} in \"{w}\"."
    if kind == 3:
        nums = rng.sample(range(1, 100), rng.randint(3, 6))
        return f"Sort these numbers from smallest to largest: {', '.join(map(str, nums))}.", ", ".join(map(str, sorted(nums)))
    if kind == 4:
        a, b = rng.sample(range(0, 1000), 2)
        return f"Which number is larger, {a} or {b}?", f"{max(a, b)} is larger than {min(a, b)}."
    return f"Spell \"{w}\" backwards.", w[::-1]


# ---- python -----------------------------------------------------------------------------------------------
PY_TASKS: list[tuple[str, str, str, list[tuple[tuple, Any]]]] = [
    ("add two numbers", "add", "def add(a, b):\n    \"\"\"Return the sum of a and b.\"\"\"\n    return a + b",
     [((2, 3), 5), ((-1, 1), 0)]),
    ("return the largest number in a list", "largest",
     "def largest(numbers):\n    \"\"\"Return the largest number in a non-empty list.\"\"\"\n    best = numbers[0]\n"
     "    for n in numbers[1:]:\n        if n > best:\n            best = n\n    return best",
     [(([3, 9, 2],), 9), (([-5, -2],), -2)]),
    ("reverse a string", "reverse", "def reverse(text):\n    \"\"\"Return text reversed.\"\"\"\n    return text[::-1]",
     [(("moth",), "htom"), (("",), "")]),
    ("check whether a number is even", "is_even",
     "def is_even(n):\n    \"\"\"Return True if n is even.\"\"\"\n    return n % 2 == 0", [((4,), True), ((7,), False)]),
    ("compute a factorial", "factorial",
     "def factorial(n):\n    \"\"\"Return n! for n >= 0.\"\"\"\n    result = 1\n    for i in range(2, n + 1):\n"
     "        result *= i\n    return result", [((0,), 1), ((5,), 120)]),
    ("count the vowels in a string", "count_vowels",
     "def count_vowels(text):\n    \"\"\"Return how many vowels (a, e, i, o, u) text contains.\"\"\"\n"
     "    return sum(1 for ch in text.lower() if ch in \"aeiou\")", [(("Moth",), 1), (("education",), 5)]),
    ("sum the numbers in a list", "total",
     "def total(numbers):\n    \"\"\"Return the sum of a list of numbers.\"\"\"\n    s = 0\n    for n in numbers:\n"
     "        s += n\n    return s", [(([1, 2, 3],), 6), (([],), 0)]),
    ("remove duplicates from a list while keeping the order", "unique",
     "def unique(items):\n    \"\"\"Return items without duplicates, in their first order.\"\"\"\n    seen = set()\n"
     "    out = []\n    for x in items:\n        if x not in seen:\n            seen.add(x)\n            out.append(x)\n"
     "    return out", [(([1, 2, 1, 3, 2],), [1, 2, 3]), (([],), [])]),
    ("check whether a word is a palindrome", "is_palindrome",
     "def is_palindrome(word):\n    \"\"\"Return True if word reads the same backwards.\"\"\"\n    return word == word[::-1]",
     [(("level",), True), (("moth",), False)]),
    ("return the n-th Fibonacci number", "fibonacci",
     "def fibonacci(n):\n    \"\"\"Return the n-th Fibonacci number (fibonacci(0) == 0).\"\"\"\n    a, b = 0, 1\n"
     "    for _ in range(n):\n        a, b = b, a + b\n    return a", [((0,), 0), ((10,), 55)]),
]
PY_PROMPTS = ["Write a Python function to {task}.", "Write a Python function that can {task}.",
              "How do I {task} in Python?"]


def passes(code: str, name: str, tests: list[tuple[tuple, Any]]) -> bool:
    """Execute generated code against its tests in an isolated namespace."""
    ns: dict[str, Any] = {"__builtins__": SAFE_BUILTINS}
    try:
        exec(compile(code, "<synthetic>", "exec"), ns)  # noqa: S102 — MOTH's own templates, no imports allowed
        fn: Callable = ns[name]
        return all(fn(*args) == want for args, want in tests)
    except Exception:  # noqa: BLE001
        return False


def python(rng: random.Random) -> tuple[str, str] | None:
    task, name, code, tests = rng.choice(PY_TASKS)
    if not passes(code, name, tests):
        return None
    args, want = tests[0]
    call = f"{name}({', '.join(map(repr, args))})"
    return rng.choice(PY_PROMPTS).format(task=task), f"```python\n{code}\n```\n\nFor example, `{call}` returns `{want!r}`."


GENERATORS = {"arithmetic": arithmetic, "instructions": instructions, "python": python}
DOMAINS = {"arithmetic": "math", "instructions": "conversation", "python": "code"}


def generate(kind: str, n: int, seed: int = 0, source_id: str | None = None) -> Iterator[dict[str, Any]]:
    """``n`` verified examples as Data Factory records (with ``messages``, so the loss is masked)."""
    if kind not in GENERATORS:
        raise ValueError(f"unknown synthetic kind {kind!r}")
    rng = random.Random(f"{kind}:{seed}")
    sid = source_id or f"synthetic-{kind}"
    made = attempts = 0
    while made < n and attempts < n * 5:
        attempts += 1
        ex = GENERATORS[kind](rng)
        if ex is None:
            continue
        q, a = ex
        yield {"uid": f"{sid}:{made}", "source": sid, "domain": DOMAINS[kind], "messages": _msgs(q, a)}
        made += 1
